        rule => undef
    );

    my $new_ctx = $ctx->fmap(sub { $_[0] * 2 });

    is($new_ctx->extract, 20, 'fmap transforms focus');
    is($ctx->extract, 10, 'original context unchanged');
    is_deeply($new_ctx->children, $ctx->children, 'children preserved by fmap');
}

