    );

    my $child2 = Chalk::EvalContext->new(
        focus => "second",
        children => [],
        start_pos => 5,
        end_pos => 11,
        env => {},
        grammar => undef,
        rule => undef
    );

    my $parent = Chalk::EvalContext->new(
        focus => "parent",
        children => [$child1, $child2],
        start_pos => 0,
        end_pos => 11,
        env => {},
        grammar => undef,
        rule => undef
    );

