   304→  # here, but performance testing shows left-recursion is already faster than
   305→  # right-recursion in our Earley implementation, so it's not needed.
   306→        if (   @waiting_for_lhs == 1
   307→            && @leo_waiting == 0
   308→            && $waiting_for_lhs[0]->rule->is_right_recursive
   309→            && $waiting_for_lhs[0]->dot_pos ==
   310→            scalar( $waiting_for_lhs[0]->rule->rhs->@* ) - 1 )
   311→        {
   312→            my $waiting_item = $waiting_for_lhs[0];
   313→
   314→            # Use completed item's end position
   315→            my $leo = Chalk::LeoItem->new(
   316→                symbol    => $lhs,
   317→                start_pos => $waiting_item->start_pos,
