   339→            my $new_item = Chalk::EarleyItem->new(
   340→                start_pos => $waiting_item->start_pos,
   341→                rule      => $waiting_item->rule,
   342→                dot_pos   => $waiting_item->dot_pos + 1,
   343→                end_pos   => $completed_item->end_pos
   344→            );
