   410→            my $advanced_item = Chalk::EarleyItem->new(
   411→                start_pos => $item->start_pos,
   412→                rule      => $item->rule,
   413→                dot_pos   => $item->dot_pos + 1,
   414→                end_pos   => $item->end_pos
