   417→            # Only add if not already present
   418→            unless ( $chart->has_item($advanced_item) ) {
   419→                my $current_element = $chart->get_element($item);
   420→                if ($current_element) {
   421→                    $chart->add_element( $advanced_item, $current_element );
   422→                    push( @$agenda, $advanced_item );
