package Chalk::Grammar::BNF::Rule::GrammarRule;
# ABOUTME: Semantic action for GrammarRule - builds [LHS, RHS] array for Grammar
# ABOUTME: Extracts nonterminal name and RHS elements

use 5.42.0;
