        # Extract LHS (nonterminal name)
        my $lhs = $children[0];

        # Extract RHS (array of symbols)
        my $rhs = $children[4] // [];
        $rhs = [] unless ref($rhs) eq 'ARRAY';

        # Return rule in format expected by build_grammar: [LHS, RHS]
        return [$lhs, $rhs];
    }
}

