     8→class Chalk::EarleyItem {
     9→    use overload '""' => 'key';
    10→
    11→    field $start_pos :param :reader;
    12→    field $rule      :param :reader;
    13→    field $dot_pos   :param :reader;
    14→    field $end_pos   :param :reader;
    15→    field $rule_id = $rule->id;
    16→    field @rhs     = $rule->rhs->@*;
    17→    field $complete    :reader = $dot_pos >= scalar(@rhs);
    18→    field $next_symbol :reader = $complete ? '' : $rhs[$dot_pos];
    19→    field $key = "Earley|$start_pos|$rule_id|$dot_pos|$end_pos";
    20→
    21→    method advance_dot() {
    22→        Chalk::EarleyItem->new(
    23→            start_pos => $start_pos,
    24→            rule      => $rule,
    25→            dot_pos   => $dot_pos + 1,
    26→            end_pos   => $end_pos,
    27→        );
    28→    }
    29→
    30→    method key(@) { $key }
    31→}
    32→
    33→# Leo Items: Limited optimization for right-recursive grammar patterns
    34→#
    35→# This is a LIMITED implementation of Joop Leo's optimization (1991) for right-recursive
    36→# grammars.  It creates "Leo items" only in DETERMINISTIC cases where:
    37→# 1. Exactly one Earley item is waiting for the completed symbol
    38→# 2. The waiting item will be complete after this one reduction
    39→# 3. The rule is right-recursive (LHS appears as last RHS symbol)
    40→#
    41→# Why limited? Full Leo would create items even with multiple waiting items and maintain
    42→# a hash lookup by (position, symbol). Our grammar has 41 right-recursive rules, but
    43→# performance testing shows grammar complexity (960+ rules) is the main bottleneck,
    44→# not right-recursion specifically. This limited implementation provides O(n) behavior
    45→# for simple right-recursive chains (ArrowChain, StatementList) without the complexity
    46→# of full Leo.
    47→#
    48→# See t/optimization/test-leo-items.t for verification tests.
    49→# See issue #10 for detailed analysis and rationale.
    50→class Chalk::LeoItem {
    51→    use overload '""' => 'key';
    52→
    53→    field $symbol    :param :reader;
    54→    field $start_pos :param :reader;
    55→    field $end_pos   :param :reader;
    56→    field $top_item  :param :reader;
    57→    field $rule      :reader = $top_item->rule;
    58→
    59→    method complete()    { 1 }
    60→    method next_symbol() { }
    61→
    62→    method key(@) {
    63→        return "LEO:$symbol|$start_pos|$end_pos";
    64→    }
    65→
    66→}
    67→
    68→class Chalk::EarleyChart {
    69→    field $semiring :param;
    70→    field %chart;
    71→    field @by_end_pos;
    72→    field %predicted;    # Track what we've predicted at each position
    73→    field %completed;    # Track what we've completed
    74→    field %waiting_for;  # Index: waiting_for{symbol}{pos} = [items waiting for symbol at pos]
    75→    field %leo_waiting_for;  # Index: leo_waiting_for{symbol}{pos} = [Leo items waiting for symbol at pos]
    76→
    77→    method add_item($earley_item) {
    78→        $chart{ $earley_item->key } = $earley_item;
    79→    }
    80→
    81→    method get_element($key) { $chart{$key} }
    82→
    83→    method add_element( $item, $element ) {
    84→        my $key     = $item->key;
    85→        my $current = $self->get_element($key);
    86→        $chart{$key} = $current ? $current + $element : $element;
    87→
    88→        push( $by_end_pos[ $item->end_pos ]->@*, $item );
    89→
    90→        # Index by what they're waiting for
    91→        if ($item isa Chalk::LeoItem) {
    92→            # Leo items are indexed by their symbol and end position
    93→            my $symbol = $item->symbol;
    94→            push @{$leo_waiting_for{$symbol}{$item->end_pos} //= []}, $item;
    95→        }
    96→        elsif (!$item->complete) {
    97→            # Regular items indexed by next_symbol
    98→            my $next_sym = $item->next_symbol;
    99→            if ($next_sym) {
   100→                push @{$waiting_for{$next_sym}{$item->end_pos} //= []}, $item;
   101→            }
   102→        }
   103→
   104→        return $chart{$key};
   105→    }
   106→
   107→    method items_ending_at($end_pos) {
   108→        return $by_end_pos[$end_pos]->@* if $by_end_pos[$end_pos];
   109→        return;
   110→    }
   111→
   112→    method items_waiting_for($symbol, $pos) {
   113→        return $waiting_for{$symbol}{$pos}->@* if exists($waiting_for{$symbol}{$pos});
   114→        return;
   115→    }
   116→
   117→    method leo_items_waiting_for($symbol, $pos) {
   118→        return $leo_waiting_for{$symbol}{$pos}->@* if exists($leo_waiting_for{$symbol}{$pos});
   119→        return;
   120→    }
   121→
   122→    method has_item($item) {
   123→        return exists( $chart{$item} );
   124→    }
   125→
   126→    method has_predicted( $nonterminal, $pos, $rule_id ) {
   127→        return exists( $predicted{"$nonterminal|$pos|$rule_id"} );
   128→    }
   129→
   130→    method mark_predicted( $nonterminal, $pos, $rule_id ) {
   131→        $predicted{"$nonterminal|$pos|$rule_id"} = 1;
   132→    }
   133→
   134→    method has_completed($item) {
   135→        return exists( $completed{$item} );
   136→    }
   137→
   138→    method mark_completed($item) {
   139→        $completed{$item} = 1;
   140→    }
   141→
   142→    method goal_value( $start_symbol, $n ) {
   143→
   144→        # Find all complete items that span [0,n] with LHS = start_symbol
   145→        my $result = $semiring->add_id;
   146→
   147→        my @items = $self->items_ending_at($n);
   148→
   149→        for my $item (@items) {
   150→            next unless $item->complete;
   151→            next unless $item->start_pos == 0;
   152→            next unless $item->rule->lhs eq $start_symbol;
   153→
   154→            my $element = $self->get_element($item);
   155→            if ($element) {
   156→                $result = $result + $element;
   157→
   158→                # Early termination for Boolean semiring: we only need to know
   159→                # IF a parse exists, not enumerate ALL parses. This prevents
   160→                # memory exhaustion when parsing highly ambiguous inputs like
   161→                # the grammar file itself (which has exponentially many parses).
   162→                if ($result != $semiring->add_id) {
   163→                    return $result;
   164→                }
   165→            }
   166→        }
   167→
   168→        # Check if we found any valid parses
   169→        return $result == $semiring->add_id ? undef : $result;
   170→    }
   171→}
   172→
   173→class Chalk::Parser {
   174→    field $semiring :param = Chalk::Semiring::Boolean->new();
   175→    field $grammar :param;
   176→    field $preprocess :param = [];  # Arrayref of preprocessor class names
   177→    field $input_string;  # Store input string for semantic actions
   178→
   179→    method parse_string($input) {
   180→        $input_string = $input;  # Store for semantic actions
   181→        # Apply preprocessors in sequence
   182→        for my $preprocessor_class (@$preprocess) {
   183→            next unless defined $preprocessor_class;
   184→
   185→            # Load the preprocessor module
   186→            (my $file = $preprocessor_class) =~ s|::|/|g;
   187→            require "$file.pm";
   188→
   189→            # Apply preprocessing
   190→            my $preprocessor = $preprocessor_class->new(input => $input);
   191→            $preprocessor->transform();
   192→            $input = $preprocessor->output;
   193→        }
   194→
   195→        my $chart = Chalk::EarleyChart->new( semiring => $semiring );
   196→
   197→       # Initialize chart by predicting all rules for start symbol at position 0
   198→        my $start_symbol = $grammar->start_symbol;
   199→        for my $rule ( $grammar->rules_for($start_symbol) ) {
   200→            my $start_item = Chalk::EarleyItem->new(
   201→                start_pos => 0,
   202→                rule      => $rule,
   203→                dot_pos   => 0,
   204→                end_pos   => 0,
   205→            );
   206→
   207→            my $start_element = $semiring->init_element_from_rule($rule, 0, 0);
   208→            $chart->add_element( $start_item, $start_element );
   209→        }
   210→
   211→        # Process positions from 0 to end of string
   212→        my $pos             = 0;
   213→        my $input_length    = length($input);
   214→        my $last_active_pos = 0;
   215→
   216→        # Store input_string for semantic actions
   217→        $input_string = $input;
   218→
   219→        while ( $pos <= $input_length ) {
   220→            my @agenda_before = $chart->items_ending_at($pos);
   221→            $self->process_position_string( $pos, $chart, $input );
   222→
   223→            # Track the last position where we had active items
   224→            if ( @agenda_before > 0 ) {
   225→                $last_active_pos = $pos;
   226→            }
   227→
   228→            ++$pos;
   229→        }
   230→
   231→        my $result =
   232→          $chart->goal_value( $grammar->start_symbol, $input_length );
   233→
   234→        # Show where parsing actually stopped if it failed
   235→        if ( !$result && $last_active_pos < $input_length ) {
   236→            warn(
   237→"🔍 PARSING STOPPED: Reached position $last_active_pos of $input_length ("
   238→                  . sprintf( "%.1f", 100 * $last_active_pos / $input_length )
   239→                  . "%)\n" );
   240→        }
   241→
   242→        return $result;
   243→    }
   244→
   245→    method process_position_string( $pos, $chart, $input_string ) {
   246→        my @agenda = $chart->items_ending_at($pos);
   247→
   248→        while ( my $item = shift(@agenda) ) {
   249→            my $element = $chart->get_element($item);
   250→            next unless defined($element);
   251→
   252→            if ( $item->complete ) {
   253→                $self->complete( $item, $element, $chart, \@agenda );
   254→            }
   255→            elsif ( defined( my $next_sym = $item->next_symbol ) ) {
   256→                if ( $grammar->is_nonterminal($next_sym) ) {
   257→                    $self->predict( $item, $next_sym, $chart, \@agenda );
   258→                }
   259→                else {
   260→                    # Try to match terminal with lexeme support
   261→                    my $pattern = $item->rule->terminal_to_regex($next_sym);
   262→                    pos($input_string) = $pos;
   263→                    if ( $input_string =~ /\G($pattern)/gc ) {
   264→                        my $match_length = length($1);
   265→                        $self->scan( $item, $element, $chart, $pos,
   266→                            $match_length );
   267→                    }
   268→
   269→                    # Aycock-Horspool optimization for nullable terminals:
   270→                    # If the terminal can match empty string, also advance dot
   271→                    if (ref($next_sym) eq 'Regexp' && "" =~ $next_sym) {
   272→                        my $advanced_item = Chalk::EarleyItem->new(
   273→                            start_pos => $item->start_pos,
   274→                            rule      => $item->rule,
   275→                            dot_pos   => $item->dot_pos + 1,
   276→                            end_pos   => $item->end_pos
   277→                        );
   278→
   279→                        unless ( $chart->has_item($advanced_item) ) {
   280→                            $chart->add_element( $advanced_item, $element );
   281→                            push( @agenda, $advanced_item );
   282→                        }
   283→                    }
   284→                }
   285→            }
   286→        }
   287→    }
   288→
   289→    method complete( $completed_item, $completed_element, $chart, $agenda ) {
   290→
   291→        # Check if we've already completed this item
   292→        return if $chart->has_completed($completed_item);
   293→        $chart->mark_completed($completed_item);
   294→
   295→        my $lhs = $completed_item->rule->lhs;
   296→
   297→        # For Semantic semiring, evaluate the completed rule
   298→        # NOTE: We evaluate and set the focus, but keep the children so they can
   299→        # be accessed by parent rules during their evaluation
   300→        if ($semiring isa Chalk::Semiring::Semantic) {
   301→            my $ctx = $completed_element->context;
   302→            my $evaluated_value = $completed_item->rule->evaluate($ctx);
   303→
   304→            # Create new context with evaluated focus but preserve children
   305→            my $new_ctx = Chalk::EvalContext->new(
   306→                focus => $evaluated_value,
   307→                children => $ctx->children,
   308→                start_pos => $ctx->start_pos,
   309→                end_pos => $ctx->end_pos,
   310→                env => $ctx->env,
   311→                grammar => $ctx->grammar,
   312→                rule => $ctx->rule
   313→            );
   314→
   315→            # Update the completed element with evaluated context
   316→            $completed_element = Chalk::Semiring::SemanticElement->new(
   317→                value => 1,
   318→                context => $new_ctx
   319→            );
   320→
   321→            # Update the chart with the evaluated element so it's available for goal_value
   322→            $chart->add_element($completed_item, $completed_element);
   323→        }
   324→
   325→        # Use indexed lookups to get items waiting for this symbol
   326→        # This avoids the expensive grep operations with isa checks
   327→        my @waiting_for_lhs = $chart->items_waiting_for($lhs, $completed_item->start_pos);
   328→        my @leo_waiting = $chart->leo_items_waiting_for($lhs, $completed_item->start_pos);
   329→
   330→  # Check for deterministic reduction (only if no Leo items waiting)
   331→  # Leo items are only for deterministic right-recursive chains where:
   332→  # 1. Only one item is waiting for this LHS
   333→  # 2. The waiting item will be complete after this reduction
   334→  # 3. The rule is right-recursive
   335→  #
   336→  # NOTE: Joop Leo's second optimization for left-recursion could be implemented
   337→  # here, but performance testing shows left-recursion is already faster than
   338→  # right-recursion in our Earley implementation, so it's not needed.
   339→        if (   @waiting_for_lhs == 1
   340→            && @leo_waiting == 0
   341→            && $waiting_for_lhs[0]->rule->is_right_recursive
   342→            && $waiting_for_lhs[0]->dot_pos ==
   343→            scalar( $waiting_for_lhs[0]->rule->rhs->@* ) - 1 )
   344→        {
   345→            my $waiting_item = $waiting_for_lhs[0];
   346→
   347→            # Use completed item's end position
   348→            my $leo = Chalk::LeoItem->new(
   349→                symbol    => $lhs,
   350→                start_pos => $waiting_item->start_pos,
   351→                end_pos   => $completed_item->end_pos,
   352→                top_item  => $waiting_item,
   353→            );
   354→
   355→            my $waiting_element = $chart->get_element($waiting_item);
   356→            next unless $waiting_element;
   357→            my $combined_element = $waiting_element * $completed_element;
   358→            $chart->add_element( $leo, $combined_element );
   359→            push( @$agenda, $leo );
   360→            return;    # Skip normal completion
   361→        }
   362→
   363→        # Normal completion for regular items
   364→        for my $waiting_item (@waiting_for_lhs) {
   365→
   366→            my $waiting_element = $chart->get_element($waiting_item);
   367→            next unless $waiting_element;
   368→
   369→            # Semiring multiplication ⊗ combines sequential components
   370→            my $combined_element = $waiting_element * $completed_element;
   371→
   372→            my $new_item = Chalk::EarleyItem->new(
   373→                start_pos => $waiting_item->start_pos,
   374→                rule      => $waiting_item->rule,
   375→                dot_pos   => $waiting_item->dot_pos + 1,
   376→                end_pos   => $completed_item->end_pos
   377→            );
   378→
   379→            # Only add if not already in chart
   380→            unless ( $chart->has_item($new_item) ) {
   381→                $chart->add_element( $new_item, $combined_element );
   382→                push( @$agenda, $new_item );
   383→            }
   384→        }
   385→
   386→        # Handle Leo items waiting for this completion
   387→        for my $leo_item (@leo_waiting) {
   388→
   389→            # Unpack the Leo chain to get the original waiting item
   390→            my $current = $leo_item->top_item;
   391→            while ( $current isa Chalk::LeoItem ) {
   392→                $current = $current->top_item;
   393→            }
   394→
   395→            # Now $current is the original EarleyItem at the bottom of the chain
   396→            # Complete it with the current completed item
   397→            my $waiting_element = $chart->get_element($leo_item);
   398→            next unless $waiting_element;
   399→            my $combined_element = $waiting_element * $completed_element;
   400→
   401→            my $new_item = Chalk::EarleyItem->new(
   402→                start_pos => $current->start_pos,
   403→                rule      => $current->rule,
   404→                dot_pos   => $current->dot_pos + 1,
   405→                end_pos   => $completed_item->end_pos
   406→            );
   407→
   408→            # Only add if not already in chart
   409→            unless ( $chart->has_item($new_item) ) {
   410→                $chart->add_element( $new_item, $combined_element );
   411→                push( @$agenda, $new_item );
   412→            }
   413→        }
   414→    }
   415→
   416→    method predict( $item, $nonterminal, $chart, $agenda ) {
   417→        my $pos = $item->end_pos;
   418→
   419→# Check if we've already predicted this nonterminal from this rule at this position
   420→# Multiple rules can predict the same nonterminal, so we track by rule origin
   421→        return if $chart->has_predicted( $nonterminal, $pos, $item->rule->id );
   422→        $chart->mark_predicted( $nonterminal, $pos, $item->rule->id );
   423→
   424→        for my $rule ( $grammar->rules_for($nonterminal) ) {
   425→            my $predicted_item = Chalk::EarleyItem->new(
   426→                start_pos => $pos,
   427→                rule      => $rule,
   428→                dot_pos   => 0,
   429→                end_pos   => $pos
   430→            );
   431→
   432→            # Only add if not already in chart
   433→            unless ( $chart->has_item($predicted_item) ) {
   434→                my $rule_element = $semiring->init_element_from_rule($rule, $pos, $pos);
   435→                $chart->add_element( $predicted_item, $rule_element );
   436→                push( @$agenda, $predicted_item );
   437→            }
   438→        }
   439→
   440→        # Aycock-Horspool optimization: if the nonterminal is nullable,
   441→        # we can also advance the dot past it immediately
   442→        if ( $grammar->is_nullable($nonterminal) ) {
   443→            my $advanced_item = Chalk::EarleyItem->new(
   444→                start_pos => $item->start_pos,
   445→                rule      => $item->rule,
   446→                dot_pos   => $item->dot_pos + 1,
   447→                end_pos   => $item->end_pos
   448→            );
   449→
   450→            # Only add if not already present
   451→            unless ( $chart->has_item($advanced_item) ) {
   452→                my $current_element = $chart->get_element($item);
   453→                if ($current_element) {
   454→                    $chart->add_element( $advanced_item, $current_element );
   455→                    push( @$agenda, $advanced_item );
   456→                }
   457→            }
   458→        }
   459→    }
   460→
   461→    method scan( $item, $element, $chart, $pos, $match_length ) {
   462→        my $scanned_item = Chalk::EarleyItem->new(
   463→            start_pos => $item->start_pos,
   464→            rule      => $item->rule,
   465→            dot_pos   => $item->dot_pos + 1,
   466→            end_pos   => $pos + $match_length
   467→        );
   468→
   469→        # For Semantic semiring, extract the matched terminal string value
   470→        my $scanned_element;
   471→        if ($semiring isa Chalk::Semiring::Semantic) {
   472→            # Extract the matched terminal value from input string
   473→            my $matched_value = substr($input_string, $pos, $match_length);
   474→
   475→            # Create a context with the terminal value as focus
   476→            my $ctx = Chalk::EvalContext->new(
   477→                focus => $matched_value,
   478→                children => [],
   479→                start_pos => $pos,
   480→                end_pos => $pos + $match_length,
   481→                env => $semiring->grammar->start_symbol,  # Use grammar
   482→                grammar => $grammar,
   483→                rule => $item->rule
   484→            );
   485→
   486→            $scanned_element = Chalk::Semiring::SemanticElement->new(
   487→                value => 1,
   488→                context => $ctx
   489→            );
   490→        } else {
   491→            # All other semirings receive position updates during scan
   492→            # Semirings can choose to use or ignore positions based on their needs
   493→            $scanned_element = $semiring->init_element_from_rule(
   494→                $item->rule,
   495→                $scanned_item->start_pos,
   496→                $scanned_item->end_pos
   497→            );
   498→        }
   499→
   500→        $chart->add_element( $scanned_item, $scanned_element );
   501→    }
   502→}
   503→
   504→1;
   505→

