package Chalk::Grammar::BNF::Rule::LineList;
# ABOUTME: Semantic action for LineList rules - collects lines into array
# ABOUTME: Handles empty, single line, and multiple lines recursively

use 5.42.0;
use experimental 'class';

class Chalk::Grammar::BNF::Rule::LineList :isa(Chalk::GrammarRule) {
    method evaluate($context) {
        my @children = map { $_->extract } $context->children->@*;
        warn "LineList.evaluate: children count = " . scalar(@children) . "\n";

        # LineList -> []  (empty)
        if (@children == 0) {
            warn "LineList.evaluate: empty, returning []\n";
            return [];
        }

        # LineList -> Line  (single line)
        if (@children == 1) {
            my $line = $children[0];
            warn "LineList.evaluate: single line = " . (defined($line) ? ref($line) || $line : "undef") . "\n";
            return defined($line) ? [$line] : [];
        }

        # LineList -> Line LineList  (multiple lines)
        if (@children == 2) {
            my ($line, $rest) = @children;
            warn "LineList.evaluate: line = " . (defined($line) ? ref($line) || $line : "undef") . "\n";
            warn "LineList.evaluate: rest = " . (defined($rest) ? ref($rest) || $rest : "undef") . "\n";
            my @result = ();
            push @result, $line if defined($line);

            if (ref($rest) eq 'ARRAY') {
                push @result, @$rest;
            }

            warn "LineList.evaluate: returning " . scalar(@result) . " items\n";
            return \@result;
        }

        return [];
    }
}

