    warn "SemanticElement.add: self_children=$self_children, other_children=$other_children\n";

    if ($other_children > $self_children) {
        warn "SemanticElement.add: choosing other\n";
        return $other;
    }

    # Otherwise prefer self (first alternative)
    warn "SemanticElement.add: choosing self\n";
