          # Create new context with evaluated focus but preserve children
          my $new_ctx = Chalk::EvalContext->new(
              focus => $evaluated_value,
              children => $ctx->children,
              start_pos => $ctx->start_pos,
              end_pos => $ctx->end_pos,
              env => $ctx->env,
              grammar => $ctx->grammar,
              rule => $ctx->rule
