package Chalk::Grammar::BNF::Rule::Line;
# ABOUTME: Semantic action for Line rules - extracts grammar rules and ignores comments
# ABOUTME: Returns the rule content or undef for comments/blank lines

use 5.42.0;
use experimental 'class';

class Chalk::Grammar::BNF::Rule::Line :isa(Chalk::GrammarRule) {
    method evaluate($context) {
        my @children = map { $_->extract } $context->children->@*;
        warn "Line.evaluate: children = " . scalar(@children) . "\n";
        if (@children > 0) {
            warn "Line.evaluate: child[0] = " . (defined($children[0]) ? ref($children[0]) || $children[0] : "undef") . "\n";
        }

        # Line -> GrammarRule '\n'
        # Line -> PatternDef '\n'
        # Return the first child (the actual content, not the newline)
        if (@children >= 1) {
            warn "Line.evaluate: returning child[0]\n";
            return $children[0];
        }

        # Line -> BlankLine or Line -> Comment '\n'
        # Return undef to signal this should be filtered out
        warn "Line.evaluate: no children, returning undef\n";
        return undef;
    }
}

