        my ($self, $completed_item, $completed_element, $chart, $agenda) = @_;
        my $lhs = $completed_item->rule->lhs;
        if ($lhs eq "Line") {
            my $ctx = $completed_element->context;
            my $children_count = scalar(@{$ctx->children});
            warn "complete(Line): element has $children_count children before evaluate\n";
            # Get latest from chart
            my $latest = $chart->get_element($completed_item);
            if ($latest) {
                my $latest_children = scalar(@{$latest->context->children});
                warn "complete(Line): LATEST from chart has $latest_children children\n";
            }
        }
        return $old_complete->($self, $completed_item, $completed_element, $chart, $agenda);
    };
}

