# ABOUTME: Simple BNF file parser for loading grammar rules
# ABOUTME: Avoids complex nested structures for bootstrap self-hosting
package Chalk::BNF;
use 5.42.0;
use utf8;
use Chalk::Grammar;
use Chalk::Grammar::BNF;
use Chalk::Parser;
use Chalk::Semiring::Semantic;

sub parse_bnf_file($filename) {
    open my $fh, '<:utf8', $filename or die "Cannot open $filename: $!";
    my $content = do { local $/; <$fh> };
    close $fh;

    return parse_bnf_string($content);
}

sub parse_with_semantic_actions($bnf_content) {
    # Parse BNF using hand-coded BNF grammar with semantic actions
    # Returns Chalk::Grammar object directly from parsing
    #
    # NOTE: The hand-coded BNF grammar currently supports basic BNF syntax
    # (grammar rules, terminals, nonterminals, pattern definitions, comments).
    # More complex features in perl.bnf may not parse yet. Use parse_bnf_string()
    # for full compatibility with existing BNF files.

    my $bnf_grammar = Chalk::Grammar::BNF->grammar;

    my $semiring = Chalk::Semiring::Semantic->new(
        env => {},
        grammar => $bnf_grammar
    );

    my $parser = Chalk::Parser->new(
        grammar => $bnf_grammar,
        semiring => $semiring
    );

    my $result = $parser->parse_string($bnf_content);

    # Extract Grammar object from semantic result
    return $result ? $result->context->extract : undef;
}

sub build_chalk_grammar($bnf_content, $start_symbol = undef) {
    my $rules = parse_bnf_string($bnf_content);

    # If start symbol specified, ensure it's first
    if (defined $start_symbol) {
        my @ordered_rules = (
            (grep { $_->[0] eq $start_symbol } @$rules),
            (grep { $_->[0] ne $start_symbol } @$rules)
        );
        $rules = \@ordered_rules;
    }

    return Chalk::Grammar->build_grammar(rules => $rules);
}

sub parse_bnf_string($content) {
    my %patterns;
    my @rules;

    my @lines = split /\n/, $content;
    for my $line (@lines) {
        $line = trim($line);

        # Skip blank lines
        next if $line eq '';

        # Pattern definition: %NAME% = /regex/flags
        # Must match before comment stripping since patterns may contain #
        if ( $line =~ /^%(\w+)%\s*=\s*\/(.+)\/([a-z]*)/ ) {
            my ( $name, $pattern, $flags ) = ( $1, $2, $3 || '' );
            $patterns{$name} = qr/(?$flags:$pattern)/;
            next;
        }

        # Strip comments AFTER checking for pattern definitions
        $line =~ s/#.*$//;
        $line = trim($line);
        next if $line eq '';

        # Grammar rule: LHS -> RHS
        if ( $line =~ /^(\w+)\s*->\s*(.*)$/ ) {
            my ( $lhs, $rhs ) = ( $1, $2 );

            # Empty RHS means epsilon rule
            if ( $rhs eq '' ) {
                push @rules, [ $lhs => [] ];
                next;
            }

            # Parse RHS tokens
            my @rhs_tokens = parse_rhs( $rhs, \%patterns );
            push @rules, [ $lhs => \@rhs_tokens ];
        }
        else {
            die "Invalid BNF syntax: $line\n";
        }
    }

    return \@rules;
}

sub parse_rhs {
    my ( $rhs, $patterns ) = @_;
    my @tokens;

    # Tokenize RHS, handling quoted strings and regexes
    while ( $rhs =~ /\S/ ) {
        $rhs = trim($rhs);

        # Single-quoted string (terminal)
        if ( $rhs =~ /^'([^']*)'/ ) {
            push @tokens, $1;
            $rhs = substr( $rhs, length($&) );
        }

        # Pattern reference %NAME%
        elsif ( $rhs =~ /^%(\w+)%/ ) {
            my $pattern_name = $1;
            if ( exists $patterns->{$pattern_name} ) {
                push @tokens, $patterns->{$pattern_name};
            }
            else {
                die "Undefined pattern: $pattern_name\n";
            }
            $rhs = substr( $rhs, length($&) );
        }

        # Regex pattern /pattern/flags
        elsif ( $rhs =~ m{^/(.+?)/([a-z]*)?} ) {
            my ( $pattern, $flags ) = ( $1, $2 // '' );
            push @tokens, qr/(?$flags:$pattern)/;
            $rhs = substr( $rhs, length($&) );
        }

        # Nonterminal or special symbol
        elsif ( $rhs =~ /^([\w:]+|[^\s'\/]+)/ ) {
            push @tokens, $1;
            $rhs = substr( $rhs, length($&) );
        }
        else {
            last;
        }
    }

    return @tokens;
}

1;

package Chalk::Grammar::BNF;
# ABOUTME: Hand-coded BNF grammar for parsing BNF files without regex dependency
# ABOUTME: Defines BNF syntax in Perl for bootstrapping the BNF parser

use 5.42.0;
use experimental 'class';
use Chalk::Grammar;
use Chalk::Grammar::BNF::Rule::Grammar;
use Chalk::Grammar::BNF::Rule::LineList;
use Chalk::Grammar::BNF::Rule::Line;
use Chalk::Grammar::BNF::Rule::GrammarRule;
use Chalk::Grammar::BNF::Rule::RHS;
use Chalk::Grammar::BNF::Rule::RHSElement;
use Chalk::Grammar::BNF::Rule::Terminal;
use Chalk::Grammar::BNF::Rule::Nonterminal;
use Chalk::Grammar::BNF::Rule::PatternDef;
use Chalk::Grammar::BNF::Rule::PatternRef;
use Chalk::Grammar::BNF::Rule::Comment;
use Chalk::Grammar::BNF::Rule::BlankLine;

# Export singleton grammar instance
our $grammar;

sub grammar {
    # Works as both sub and method
    shift if @_ && (!ref($_[0]) && $_[0] eq __PACKAGE__);
    return $grammar;
}

# Helper to create rules with custom classes
sub _new_bnf_rule {
    my ($lhs, $rhs, $probability) = @_;
    $probability ||= 1.0;

    # Map LHS nonterminal to appropriate rule class
    my $rule_class = "Chalk::Grammar::BNF::Rule::$lhs";
    my $rule_file = $rule_class;
    $rule_file =~ s|::|/|g;
    $rule_file .= ".pm";

    # Check if the specialized class exists
    if (eval { require $rule_file; 1 }) {
        return $rule_class->new(
            lhs => $lhs,
            rhs => $rhs,
            probability => $probability
        );
    }

    # Fall back to default GrammarRule
    return Chalk::GrammarRule->new(
        lhs => $lhs,
        rhs => $rhs,
        probability => $probability
    );
}

# Build the BNF grammar with semantic action support
sub _build_bnf_grammar {
    my @rules_array = @_;
    my %rules = ();

    for my $r (@rules_array) {
        my ($lhs, $rhs, $prob) = @$r;
        push(@{$rules{$lhs} //= []}, _new_bnf_rule($lhs, $rhs, $prob));
    }

    return Chalk::Grammar->new(
        rules => \%rules,
        start_symbol => $rules_array[0]->[0]
    );
}

# Hand-coded BNF grammar rules
# This grammar is used to parse BNF files like grammar/perl.bnf
$grammar = _build_bnf_grammar(
        # Top level: a BNF file is a list of lines
        ['Grammar', ['LineList']],

        # Lines can be empty, a single line, or contain more lines
        ['LineList', []],  # Empty (base case)
        ['LineList', ['Line']],  # Single line
        ['LineList', ['Line', 'LineList']],  # Multiple lines

        # A line can be a pattern definition, grammar rule, comment, or blank
        # Note: lines in BNF files end with newlines (handled by Line rules)
        ['Line', ['PatternDef', "\n"]],
        ['Line', ['GrammarRule', "\n"]],
        ['Line', ['Comment', "\n"]],
        ['Line', ['BlankLine']],

        # Pattern definitions: %NAME% = /regex/flags or //regex//flags
        # Example: %PATTERN_1% = /unless|if|while/u
        # Example: %PATTERN_21% = //(?:[^/\\]|\\.)*+//u
        ['PatternDef', [
            '%',
            qr/[a-zA-Z_][a-zA-Z0-9_]*/,  # Pattern name
            '%',
            qr/\s*/,                      # Optional whitespace
            '=',
            qr/\s*/,                      # Optional whitespace
            '/',
            qr/(?:[^\/\\]|\\.)*/,         # Regex content (non-greedy, handle escapes)
            '/',
            qr/[a-z]*/                    # Optional flags
        ]],

        # Pattern definition with double-slash delimiter
        # Inside //, single / is allowed, but // is the terminator
        ['PatternDef', [
            '%',
            qr/[a-zA-Z_][a-zA-Z0-9_]*/,  # Pattern name
            '%',
            qr/\s*/,                      # Optional whitespace
            '=',
            qr/\s*/,                      # Optional whitespace
            '//',
            qr/(?:[^\/\\]++|\\.|\/(?!\/))*+/,  # Regex content (/ allowed, but not //)
            '//',
            qr/[a-z]*/                    # Optional flags
        ]],

        # Grammar rules: LHS -> RHS
        # Example: Block -> '{' WS_OPT StatementList WS_OPT '}'
        ['GrammarRule', [
            qr/[A-Z][a-zA-Z0-9_]*/,  # LHS (nonterminal, starts with capital)
            qr/\s*/,                  # Optional whitespace
            '->',
            qr/\s*/,                  # Optional whitespace
            'RHS'
        ]],

        # Right-hand side: sequence of RHS elements or empty
        ['RHS', []],  # Empty RHS (epsilon production)
        ['RHS', ['RHSElement']],
        ['RHS', ['RHSElement', qr/\s+/, 'RHS']],

        # RHS elements can be terminals, nonterminals, or pattern references
        ['RHSElement', ['Terminal']],
        ['RHSElement', ['Nonterminal']],
        ['RHSElement', ['PatternRef']],

        # Terminals: single-quoted strings
        # Example: 'foo', '{', '}'
        ['Terminal', ["'", qr/(?:[^'\\]|\\.)*/, "'"]],

        # Nonterminals: identifiers starting with capital letter
        # Example: Block, StatementList, WS_OPT
        ['Nonterminal', [qr/[A-Z][a-zA-Z0-9_]*/]],

        # Pattern references: %NAME%
        # Example: %PATTERN_1%
        ['PatternRef', [
            '%',
            qr/[a-zA-Z_][a-zA-Z0-9_]*/,
            '%'
        ]],

        # Comments: # followed by anything until newline
        ['Comment', [qr/#[^\n]*/]],

        # Blank lines: just a newline
        ['BlankLine', [qr/\n/]],
);

1;

