plenv exec perl -Ilib << 'PERL'
use 5.42.0;
use Chalk::BNF;

my $bnf = "%PATTERN_38% = /\\|\\||///u\nTest -> %PATTERN_38%\n";
say "Testing with rest-of-line approach...";

my $grammar = Chalk::BNF::parse_with_semantic_actions($bnf);
if ($grammar) {
    say "SUCCESS!";
    my @rules = $grammar->rules_for('Test');
    if (@rules) {
        my $rhs = $rules[0]->rhs;
        my $pattern = $rhs->[0];
        say "Pattern: $pattern";

        if ("||" =~ $pattern) {
            say "MATCH: ||";
        }
        if ("//" =~ $pattern) {
            say "MATCH: //";  
        }
        if ("/" =~ $pattern) {
            say "ERROR: Also matches single /";
        } else {
            say "OK: Does NOT match single /";
        }
    }
} else {
    say "FAILED";
}
PERL

