    #           [1] = whitespace (ignore)
    #           [2] = '->' (ignore)
    #           [3] = whitespace (ignore)
    #           [4] = RHS (array of symbols)
    #           [5] = optional inline comment (ignore if present)

    my @children = map { $_->extract } $context->children->@*;

