use Chalk::BNF;

# Monkey-patch parse_rhs to add debugging
{
    no warnings 'redefine';
    package Chalk::BNF;

    my $original_parse_rhs = \&parse_rhs;

    *parse_rhs = sub {
        my ($rhs_orig, $patterns) = @_;
        my $rhs = $rhs_orig;
        my @tokens;

        say STDERR "=== parse_rhs called with: '$rhs_orig'";

        while ( $rhs =~ /\S/ ) {
            $rhs = trim($rhs);
            say STDERR "  Loop: rhs='$rhs'";

            if ( $rhs =~ /^'((?:[^'\\]|\\.)*)'/ ) {
                my $content = $1;
                say STDERR "    Matched terminal: '$content' (len=" . length($content) . ")";
                say STDERR "    Match was: '$&'";

                # Unescape
                $content =~ s/\\\\/\x00/g;
                $content =~ s/\\n/\n/g;
                $content =~ s/\\t/\t/g;
                $content =~ s/\\r/\r/g;
                $content =~ s/\\'/'/g;
                $content =~ s/\x00/\\/g;

                say STDERR "    After unescape: len=" . length($content);
                push @tokens, $content;
                $rhs = substr( $rhs, length($&) );
                say STDERR "    Remaining: '$rhs'";
            }
            elsif ( $rhs =~ /^%(\w+)%/ ) {
                my $pattern_name = $1;
                if ( exists $patterns->{$pattern_name} ) {
                    push @tokens, $patterns->{$pattern_name};
                }
                $rhs = substr( $rhs, length($&) );
            }
            elsif ( $rhs =~ m{^/(.+?)/([a-z]*)?} ) {
                push @tokens, qr/(?$2:$1)/;
                $rhs = substr( $rhs, length($&) );
